{
  "findings": [
    {
      "check_id": "CKV_GCP_121 is not applicable, but the principle applies; using AVD-AWS-0177 as a reference for the concept",
      "title": "Instance does not have Deletion Protection enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The Google SQL database instance is not protected against accidental deletion because deletion_protection is set to false."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Database connection logging is disabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_connections database flag is set to 'off', which may hinder auditing and troubleshooting database connections."
    }
  ],
  "patched_code": "resource "google_sql_database_instance" "trading_database" {
  name             = "real-time-financial-trading-platform-database-trading"
  database_version = "POSTGRES_13"
  region           = var.region
  deletion_protection = true
  settings {
    tier = "db-n1-standard-2"
    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.trading_platform_vpc.id
    }
    database_flags {
      name  = "log_connections"
      value = "on"
    }
    backup_configuration {
      enabled                        = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
    }
  }
  depends_on = [google_service_networking_connection.private_vpc_connection]
}",
  "fix_summary": "Enabled deletion protection for the Google SQL database instance and turned on connection logging by setting log_connections to 'on'."
}
